import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_triu_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_pipeline_primitives.h>
#include <cute/tensor.hpp>
using namespace cute;
#define TILE 64
#define TT 4
#define SMEM_PAD 4
__device__ __forceinline__ void load_ab_tile(
    const float* __restrict__ A_ptr,
    const float* __restrict__ B_ptr,
    float* As_data,
    float* Bs_data,
    int N, int kt,
    int ry0, int cx0,
    int row_base, int col_base) {
    // Shared-memory tiles are stored row-major with a padded row stride
    // (TILE + SMEM_PAD) to avoid bank conflicts; compute addresses
    // directly so we can issue cp.async copies straight from global to
    // shared memory, bypassing registers and overlapping the transfer
    // with compute on a hardware copy engine.
    const int LD = TILE + SMEM_PAD;
    int a_col_base = kt * TILE + cx0;
    // Store the A tile transposed in shared memory (indexed as [k][row])
    // so that the compute loop can fetch a contiguous TT-wide vector of
    // "row" values for a fixed k via a single 128-bit load, mirroring the
    // vectorized access already used for B and avoiding strided
    // shared-memory reads during the much hotter compute loop.
    #pragma unroll
    for (int i = 0; i < TT; ++i) {
        int row = row_base + i;
        int row_local = ry0 + i;
        if (row < N) {
            if (a_col_base + TT - 1 < N) {
                #pragma unroll
                for (int j = 0; j < TT; ++j) {
                    float* dst = As_data + (cx0 + j) * LD + row_local;
                    const float* src = A_ptr + row * N + a_col_base + j;
                    __pipeline_memcpy_async(dst, src, sizeof(float));
                }
            } else {
                #pragma unroll
                for (int j = 0; j < TT; ++j) {
                    int col = a_col_base + j;
                    float* dst = As_data + (cx0 + j) * LD + row_local;
                    *dst = (col < N) ? A_ptr[row * N + col] : 0.f;
                }
            }
        } else {
            #pragma unroll
            for (int j = 0; j < TT; ++j) {
                float* dst = As_data + (cx0 + j) * LD + row_local;
                *dst = 0.f;
            }
        }
    }
    int b_row_base = kt * TILE + ry0;
    #pragma unroll
    for (int i = 0; i < TT; ++i) {
        int b_row = b_row_base + i;
        float* dst = Bs_data + (ry0 + i) * LD + cx0;
        if (b_row < N) {
            if (col_base + TT - 1 < N) {
                const float4* src = reinterpret_cast<const float4*>(B_ptr + b_row * N + col_base);
                __pipeline_memcpy_async(dst, src, sizeof(float4));
            } else {
                #pragma unroll
                for (int j = 0; j < TT; ++j) {
                    int col = col_base + j;
                    dst[j] = (col < N) ? B_ptr[b_row * N + col] : 0.f;
                }
            }
        } else {
            #pragma unroll
            for (int j = 0; j < TT; ++j) dst[j] = 0.f;
        }
    }
    // Commit all cp.async copies issued above as a single pipeline stage
    // so the caller can later wait on it with __pipeline_wait_prior.
    __pipeline_commit();
}
extern __shared__ float smem_dyn[];
__global__ void triu_matmul_kernel(const float* __restrict__ A_ptr,
                                    const float* __restrict__ B_ptr,
                                    float* __restrict__ C_ptr,
                                    int N) {
    int tile_row = blockIdx.y;
    int tile_col = blockIdx.x;
    // Blocks entirely below the diagonal contribute nothing to the
    // upper-triangular output; skip them completely.
    if (tile_row > tile_col) return;
    int linear_tid = threadIdx.y * blockDim.x + threadIdx.x;
    int warp_id = linear_tid / 32;
    int lane_id = linear_tid % 32;
    // Warp-level tiling: partition the 64x64 CTA tile into a 2x4 grid of
    // warps, each owning a spatially-contiguous 32x16 sub-tile, so that
    // all 32 threads in a warp read from a compact region of the
    // shared-memory tiles rather than spanning the whole 64-wide tile
    // with only 8 rows (as the previous ty/tx mapping did). This keeps
    // warp-synchronous shared-memory access patterns more localized and
    // predictable, improving effective reuse across the vectorized
    // As/Bs loads below.
    const int WARPS_M = 2;
    const int WARPS_N = 4;
    const int WARP_TILE_M = TILE / WARPS_M; // 32
    const int WARP_TILE_N = TILE / WARPS_N; // 16
    int warp_row = warp_id / WARPS_N;
    int warp_col = warp_id % WARPS_N;
    int lane_row = lane_id / 4; // 0..7
    int lane_col = lane_id % 4; // 0..3
    // Each thread computes a TTxTT (4x4) register-blocked sub-tile of C
    int ry0 = warp_row * WARP_TILE_M + lane_row * TT;
    int cx0 = warp_col * WARP_TILE_N + lane_col * TT;
    int row_base = tile_row * TILE + ry0;
    int col_base = tile_col * TILE + cx0;
    // Double-buffered shared memory tiles (dynamic shared memory) so that
    // loading the next k-tile from global memory can be overlapped with
    // the compute on the currently resident tile.
    const int TILE_ELEMS = TILE * (TILE + SMEM_PAD);
    float* As_buf[2] = { smem_dyn, smem_dyn + TILE_ELEMS };
    float* Bs_buf[2] = { smem_dyn + 2 * TILE_ELEMS, smem_dyn + 3 * TILE_ELEMS };
    Tensor gC = make_tensor(make_gmem_ptr(C_ptr), make_shape(N, N), make_stride(N, Int<1>{}));
    float acc[TT][TT];
    #pragma unroll
    for (int i = 0; i < TT; ++i)
        #pragma unroll
        for (int j = 0; j < TT; ++j)
            acc[i][j] = 0.f;
    // A is upper triangular => A(row, k) == 0 for k < row
    // B is upper triangular => B(k, col) == 0 for k > col
    // So only k-tiles in [tile_row, tile_col] can contribute.
    int kt_start = tile_row;
    int kt_end = tile_col;
    // Prefetch the first k-tile into buffer 0.
    load_ab_tile(A_ptr, B_ptr, As_buf[0], Bs_buf[0], N, kt_start, ry0, cx0, row_base, col_base);
    __pipeline_wait_prior(0);
    __syncthreads();
    for (int kt = kt_start; kt <= kt_end; ++kt) {
        int cur = (kt - kt_start) & 1;
        int nxt = cur ^ 1;
        // Kick off the asynchronous (cp.async) load of the next tile before
        // consuming the current one so the global-memory latency is hidden
        // behind the compute below via a hardware copy engine, without
        // occupying registers or ALU pipes (independent shared-memory
        // buffers, no hazard).
        bool has_next = (kt + 1 <= kt_end);
        if (has_next) {
            load_ab_tile(A_ptr, B_ptr, As_buf[nxt], Bs_buf[nxt], N, kt + 1, ry0, cx0, row_base, col_base);
            __pipeline_wait_prior(1);
        } else {
            __pipeline_wait_prior(0);
        }
        __syncthreads();
        Tensor As = make_tensor(make_smem_ptr(As_buf[cur]),
                                 make_shape(Int<TILE>{}, Int<TILE>{}),
                                 make_stride(Int<TILE + SMEM_PAD>{}, Int<1>{}));
        Tensor Bs = make_tensor(make_smem_ptr(Bs_buf[cur]),
                                 make_shape(Int<TILE>{}, Int<TILE>{}),
                                 make_stride(Int<TILE + SMEM_PAD>{}, Int<1>{}));
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            float a_reg[TT];
            float b_reg[TT];
            // As is stored transposed ([k][row]) in shared memory, so a
            // 4-wide vectorized load fetches all TT rows for the current k
            // in a single 128-bit transaction, matching the vectorized
            // access pattern already used for B and eliminating the
            // strided per-element shared-memory reads.
            float4 a4 = *reinterpret_cast<const float4*>(&As(k, ry0));
            a_reg[0] = a4.x;
            a_reg[1] = a4.y;
            a_reg[2] = a4.z;
            a_reg[3] = a4.w;
            // Bs is stored row-major with contiguous columns, so a 4-wide
            // vectorized load fetches all TT columns for the current k in
            // a single 128-bit transaction, cutting shared-memory traffic
            // and instruction count relative to four scalar loads.
            float4 b4 = *reinterpret_cast<const float4*>(&Bs(k, cx0));
            b_reg[0] = b4.x;
            b_reg[1] = b4.y;
            b_reg[2] = b4.z;
            b_reg[3] = b4.w;
            #pragma unroll
            for (int i = 0; i < TT; ++i) {
                #pragma unroll
                for (int j = 0; j < TT; ++j) {
                    acc[i][j] += a_reg[i] * b_reg[j];
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int i = 0; i < TT; ++i) {
        int row = row_base + i;
        if (row >= N) continue;
        #pragma unroll
        for (int j = 0; j < TT; ++j) {
            int col = col_base + j;
            if (col < N && row <= col) gC(row, col) = acc[i][j];
        }
    }
}
torch::Tensor cute_triu_matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "Expect float32 tensors");
    int N = (int)A.size(0);
    TORCH_CHECK((int)A.size(1) == N, "A must be square");
    TORCH_CHECK((int)B.size(0) == N && (int)B.size(1) == N, "B must be square and match A");
    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    // Zero-init since blocks fully below the diagonal, and the
    // lower-triangular part of diagonal blocks, are never written.
    auto C = torch::zeros({N, N}, A.options());
    int num_tiles = (N + TILE - 1) / TILE;
    dim3 block(TILE / TT, TILE / TT);
    dim3 grid(num_tiles, num_tiles);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    // Double-buffered A/B tiles require 4x the single-buffer shared memory
    // footprint; opt in to the larger dynamic shared-memory limit once.
    size_t smem_bytes = 4 * (size_t)TILE * (TILE + SMEM_PAD) * sizeof(float);
    static bool smem_attr_set = false;
    if (!smem_attr_set) {
        cudaFuncSetAttribute(triu_matmul_kernel,
                              cudaFuncAttributeMaxDynamicSharedMemorySize,
                              (int)smem_bytes);
        smem_attr_set = true;
    }
    triu_matmul_kernel<<<grid, block, smem_bytes, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(), N);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE triu_matmul launch failed");
    return C;
}
"""

cute_ext = load_inline(
    name="cute_triu_matmul_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_triu_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "-I/workspace/cutegen_test/cutegen/cutlass/include"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A * B) for
    upper triangular matrices using a custom fused CUTE/CUDA kernel that
    skips block computations that cannot contribute to the upper-triangular
    result.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_triu_matmul(A, B)

